import { atom, read, update } from 'claude-code'
import type { Register } from 'claude-code'

import type { CacheBreak, CacheSample, Extension, Overrides } from '../types'
import {
  EMPTY_TTL,
  EXTEND_COMMAND,
  KEEP_WARM_PROMPT,
  LANGUAGES,
  MAX_EVENTS,
  MAX_SAMPLES,
  NARROW_COLUMNS,
  NO_OVERRIDES,
  SENSITIVITIES,
  anchorOf,
  appendCapped,
  applyOverrides,
  autoExtendSteps,
  chartModel,
  contextOf,
  countdownOf,
  effectiveTtl,
  formatCauses,
  formatClock,
  formatPercent,
  formatStatus,
  formatTokens,
  fromSelect,
  guessCauses,
  hitRateOf,
  isBreak,
  isTtlState,
  learnTtl,
  legendMarks,
  normalizeOverrides,
  notePrint,
  parseCacheArgs,
  readConfig,
  readoutOf,
  recentHits,
  shouldAutoExtend,
  summarize,
  toBreak,
  toExtension,
  toSample,
  withOverride,
  withoutOverride,
} from './core'
import type { QuickSetting } from './core'
import { LANGUAGE_NAMES, STRINGS } from './i18n'
import {
  BIG_CLOCK_SIZE,
  BIG_RING_SIZE,
  CHART_BARS,
  CLOCK_SIZE,
  COLORS,
  NARROW_CHART_BARS,
  RING_SIZE,
  SPARK_HEIGHT,
  SPARK_WIDTH,
  chartSvg,
  clockSvg,
  idleRingSvg,
  pausedRingSvg,
  ringSvg,
  sparklineSvg,
} from './svg'

const samples = atom({ plugin: 'cache-bar', key: 'samples' } as const, [] as CacheSample[])
const breaks = atom({ plugin: 'cache-bar', key: 'breaks' } as const, [] as CacheBreak[])
const extensions = atom({ plugin: 'cache-bar', key: 'extensions' } as const, [] as Extension[])
const ttl = atom({ plugin: 'cache-bar', key: 'ttl' } as const, EMPTY_TTL)
// Families, one member per id: many hooks fire at once (tool.describe once per
// tool), and members never contend the way one shared value would.
const changedAt = { plugin: 'cache-bar', key: 'changedAt' } as const
const prints = { plugin: 'cache-bar', key: 'prints' } as const
const clock = atom({ plugin: 'cache-bar', key: 'now' } as const, 0)
const stage = atom({ plugin: 'cache-bar', key: 'stage' } as const, 'none')
const extending = atom({ plugin: 'cache-bar', key: 'extending' } as const, false)
const overrides = atom({ plugin: 'cache-bar', key: 'overrides' } as const, NO_OVERRIDES)
const alertedFor = atom({ plugin: 'cache-bar', key: 'alertedFor' } as const, null as number | null)

/** `$.store` key of the learned TTL, kept across sessions. */
const TTL_STORE_KEY = 'ttl'

/** `$.store` key of the settings picked in the panel. */
const OVERRIDES_STORE_KEY = 'overrides'

/** Requests the band's trend line spans. */
const SPARK_POINTS = 24

/** The side panel's id, and the command that opens it. */
const PANE = 'cache-bar'
const COMMAND = 'cache'

/** Rows the panel's break and extension lists show, newest first. */
const LIST_ROWS = 8

/** Text that needs you: the theme's error colour, so it follows light and dark. */
const TEXT_ALERT = 'error'

export const register: Register = (on, options) => {
  // The userConfig values, and those in force once the panel's picks apply.
  const base = readConfig(options)
  let config = base
  let strings = STRINGS[config.language]
  // `$.state` outlives a reload, so it may hold picks saved in an older shape.
  const applyPicks = (picked: Overrides) => {
    config = applyOverrides(base, normalizeOverrides(picked) ?? NO_OVERRIDES)
    strings = STRINGS[config.language]
  }
  let shownStatus: string | undefined
  // Once the desktop band draws, the status line would only repeat it.
  let hasBand = false
  let isWorking = false
  let isForking = false
  // Set by session.start: one keep-warm fork, resolving to what it reports
  // (null when one is already running), toasted unless `shouldToast` is false.
  // The buttons call it too, since a Button can't reach this plugin's own
  // slash command.
  let extendNow: ((trigger: Extension['trigger'], shouldToast?: boolean) => Promise<string | null>) | null = null
  // Set by session.start: applies a setting picked in the panel or with
  // `/cache lang` (as the Select's string), resolving to why it failed, or
  // null once it is done.
  let pickOption: ((field: QuickSetting, value: string) => Promise<string | null>) | null = null
  // The ring's drawing stays the same while its anchor, TTL and phase do, so
  // its SMIL countdown keeps running across the band's redraws.
  let ring = { key: '', source: '' }
  let smallClock = { key: '', source: '', width: 0, height: 0 }
  // The panel's ring and clock, kept the same way. Dropped when the panel
  // opens or closes: a fresh drawing restarts its SMIL from load.
  let bigRing = { key: '', source: '' }
  let bigClock = { key: '', source: '', width: 0, height: 0 }
  const forgetPaneDrawings = () => {
    bigRing = { key: '', source: '' }
    bigClock = { key: '', source: '', width: 0, height: 0 }
  }

  on('session.start', async ($, e, next) => {
    const stored = await $.store.get(TTL_STORE_KEY)

    if (isTtlState(stored)) {
      await update($, ttl, current => (current.detected === null ? stored : current))
    }

    const storedOverrides = normalizeOverrides(await $.store.get(OVERRIDES_STORE_KEY))

    if (storedOverrides !== null) {
      await update($, overrides, () => storedOverrides)
    }

    applyPicks(await read($, overrides))
    await $.command.register({ name: COMMAND, description: strings.commandDescription })
    await $.command.register({ name: EXTEND_COMMAND, description: strings.extendCommandDescription })

    // A reload after a language change keeps the panel up under its old title.
    const shownPane = (await $.ui.panes()).find(pane => pane.id === PANE)

    if (shownPane !== undefined && shownPane.title !== strings.paneTitle) {
      await $.ui.open({ id: PANE, title: strings.paneTitle })
    }

    extendNow = async (trigger, shouldToast = true) => {
      if (isForking) {
        return null
      }

      isForking = true
      await update($, extending, () => true)
      const sentAt = await $.clock.now()

      try {
        const outcome = await $.model.fork({ prompt: KEEP_WARM_PROMPT })
        const extension = toExtension(outcome, sentAt, trigger)
        await update($, extensions, list => appendCapped(list, extension, MAX_EVENTS))
        const readK = formatTokens(extension.read)
        const text = !outcome.isAnswered
          ? strings.extendFailed(outcome.reason)
          : trigger === 'manual'
            ? strings.extended(readK)
            : strings.autoExtended(readK)

        // A quiet auto extension stays quiet; a failure is always told.
        if (shouldToast && (trigger === 'manual' || config.toast || !outcome.isAnswered)) {
          $.ui.toast(text)
        }

        return text
      } catch (err) {
        const reason = String(err)
        const extension = toExtension({ isAnswered: false, reason }, sentAt, trigger)
        await update($, extensions, list => appendCapped(list, extension, MAX_EVENTS))
        const text = strings.extendFailed(reason)

        if (shouldToast) {
          $.ui.toast(text)
        }

        return text
      } finally {
        isForking = false
        await update($, extending, () => false)
      }
    }

    // Through `/config` where it has the row: the module reloads with the new
    // options. A plugin folder on desktop gets no rows, so the pick is kept as
    // an override instead, in `$.state` (redrawing) and `$.store`.
    pickOption = async (field, raw) => {
      const value = fromSelect(field, raw)

      if (value === null || value === config[field]) {
        return null
      }

      try {
        const rows = await $.config.list()
        const row =
          rows.find(r => r.key === `cache-bar.${field}`) ??
          rows.find(r => r.key.startsWith('cache-bar') && r.key.endsWith(`.${field}`))

        if (row === undefined) {
          await update($, overrides, o => withOverride(normalizeOverrides(o) ?? NO_OVERRIDES, base, field, value))
        } else {
          const result = await $.config.set({ key: row.key, value })

          if (result.deny !== undefined) {
            return strings.settingFailed(result.deny)
          }

          // An override kept from before the row existed would still win over
          // it while the value it replaced stands, so the row's pick drops it.
          await update($, overrides, o => withoutOverride(normalizeOverrides(o) ?? NO_OVERRIDES, field))
        }

        const picked = await read($, overrides)
        applyPicks(picked)
        await $.store.set(OVERRIDES_STORE_KEY, picked)

        if (field === 'language' && (await $.ui.panes()).some(pane => pane.id === PANE)) {
          await $.ui.open({ id: PANE, title: strings.paneTitle })
        }

        // Once the panel closes, nothing on screen leads back: say how.
        if (field === 'band' && value === 'off') {
          $.ui.toast(strings.bandTurnedOff(COMMAND))
        }

        return null
      } catch (err) {
        return strings.settingFailed(String(err))
      }
    }

    // The clock goes through $.state: a value the drawings read redraws them.
    $.clock.every(1000, async () => {
      const now = await $.clock.now()
      await update($, clock, () => now)

      const view = {
        samples: await read($, samples),
        breaks: await read($, breaks),
        extensions: await read($, extensions),
        ttl: await read($, ttl),
        config,
        isWorking,
        isExtending: isForking,
        now,
      }
      // The terminal and VS Code have no band: the status line is their display.
      const text = hasBand ? undefined : formatStatus(view, strings)

      if (text !== shownStatus) {
        shownStatus = text
        $.ui.status(text)
      }

      // Expiry notices: none while Claude answers, since each request refreshes.
      const last = view.samples.at(-1)
      const countdown = countdownOf(view.samples, view.extensions, config.ttlMode, view.ttl, config, now)
      const nextStage = isWorking
        ? 'working'
        : countdown === null
          ? 'none'
          : `${countdown.anchor}|${countdown.ttl}|${countdown.phase}`

      if ((await read($, stage)) !== nextStage) {
        await update($, stage, () => nextStage)
      }

      if (isWorking || last === undefined || countdown === null || countdown.phase !== 'alert') {
        return
      }

      if (shouldAutoExtend({ samples: view.samples, extensions: view.extensions, countdown, config, now })) {
        void extendNow?.('auto')

        return
      }

      if ((await read($, alertedFor)) === last.sentAt) {
        return
      }

      await update($, alertedFor, () => last.sentAt)

      if (config.toast) {
        const notice = strings.expiresIn(formatClock(countdown.leftMs))
        const isBandOff = hasBand && config.band === 'off'
        const hint = hasBand && !isBandOff ? strings.pressExtend : strings.runExtend(EXTEND_COMMAND)
        // With the band off, nothing on screen leads to the panel: the toast does.
        const panel = isBandOff ? ` · ${strings.openPanel(COMMAND)}` : ''
        $.ui.toast(`${config.onExpiring === 'notify' ? notice : `${notice} · ${hint}`}${panel}`)
      }
    })

    return next(e)
  })

  // `/cache` opens the panel; `/cache lang [en|zh-TW]` switches the language,
  // to the other one when none is named.
  on('command.run', { command: COMMAND }, async ($, e) => {
    const asked = parseCacheArgs(e.args, config.language)

    if (asked.kind === 'unknown') {
      return { text: strings.cacheUsage(COMMAND) }
    }

    if (asked.kind === 'language') {
      const failed = await pickOption?.('language', asked.language)

      return { text: failed ?? STRINGS[asked.language].languageSet(LANGUAGE_NAMES[asked.language]) }
    }

    forgetPaneDrawings()
    const opened = await $.ui.open({ id: PANE, title: strings.paneTitle })

    return opened.isPlaced ? {} : { text: strings.paneUnplaced(opened.reason) }
  })

  // Keeps the cache warm now, whatever the countdown says: the TTL is only an
  // estimate. The answer is the command's output line rather than a toast.
  on('command.run', { command: EXTEND_COMMAND }, async $ => {
    if ((await read($, samples)).length === 0) {
      return { text: strings.extendNothing }
    }

    if (isWorking) {
      return { text: strings.extendBusy }
    }

    const text = await extendNow?.('manual', false)

    return { text: text ?? strings.extendAlready }
  })

  on('turn.start', async ($, e, next) => {
    isWorking = true

    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    isWorking = false

    return next(e)
  })

  // Record each main-thread request's cache usage; judge breaks and the TTL.
  on('turn.step', async function* ($, e, next) {
    const sentAt = await $.clock.now()
    const step = yield* next(e)

    // Outside a turn while a keep-warm fork runs, the request is the fork's own:
    // counting it would start a new idle stretch and lift the auto-extend cap.
    if (e.agentId !== undefined || step.usage === null || (isForking && !isWorking)) {
      return step
    }

    const at = await $.clock.now()
    const previous = (await read($, samples)).at(-1)
    const sample = toSample(step.usage, sentAt, at, previous)

    if (previous !== undefined) {
      const learned = await read($, ttl)
      const marks = {
        compactAt: (await read($, { ...changedAt, id: 'compact' })) ?? null,
        systemAt: (await read($, { ...changedAt, id: 'system' })) ?? null,
        toolsAt: (await read($, { ...changedAt, id: 'tools' })) ?? null,
      }
      // A keep-warm fork refreshed the cache too: idle counts from the later of
      // the two, or a kept-warm 5m cache would read as proof of 1h.
      const forks = (await read($, extensions)).filter(x => x.at < sentAt)
      const refreshedAt = anchorOf([previous], forks) ?? previous.sentAt
      const sinceRefresh = { ...sample, idleMs: sentAt - refreshedAt }
      const causes = guessCauses(previous, sinceRefresh, marks, effectiveTtl(config.ttlMode, learned))

      if (isBreak(previous, sample, config.breakSensitivity)) {
        await update($, breaks, list => appendCapped(list, toBreak(previous, sample, causes), MAX_EVENTS))
      }

      const relearned = learnTtl(learned, previous, sinceRefresh, causes.filter(c => c !== 'idle'))

      if (relearned !== learned) {
        await update($, ttl, () => relearned)
        await $.store.set(TTL_STORE_KEY, relearned)
      }
    }

    await update($, samples, list => appendCapped(list, sample, MAX_SAMPLES))

    return step
  })

  on('session.compact', async ($, e, next) => {
    const result = await next(e)

    // `precompute` only prepares a summary; the conversation is unchanged.
    if (e.agentId === undefined && e.trigger !== 'precompute' && !('skip' in result)) {
      await $.state.set({ ...changedAt, id: 'compact' }, await $.clock.now())
    }

    return result
  })

  // The next three only watch what the prompt is built from. A change seen
  // once the conversation has started is a likely cause of a cache break.
  // Marks are plain writes: concurrent ones all write about the same time.

  on('prompt.section', async ($, e, next) => {
    const result = await next(e)
    let isChange = false
    await update($, { ...prints, id: `section:${e.name}` }, seen => {
      const noted = notePrint(seen ?? [], result.text ?? '')
      isChange = noted.isChange

      return noted.seen
    })

    if (isChange && (await read($, samples)).length > 0) {
      await $.state.set({ ...changedAt, id: 'system' }, await $.clock.now())
    }

    return result
  })

  on('prompt.context', async ($, e, next) => {
    const result = await next(e)
    let isChange = false

    for (const block of result.blocks) {
      await update($, { ...prints, id: `context:${block.name}` }, seen => {
        const noted = notePrint(seen ?? [], block.text)
        isChange ||= noted.isChange

        return noted.seen
      })
    }

    if (isChange && (await read($, samples)).length > 0) {
      await $.state.set({ ...changedAt, id: 'system' }, await $.clock.now())
    }

    return result
  })

  on('tool.describe', async ($, e, next) => {
    const result = await next(e)
    let isChange = false
    await update($, { ...prints, id: `tool:${e.tool}` }, seen => {
      const noted = notePrint(seen ?? [], `${result.description}\u0000${String(result.isDeferred)}`)
      isChange = noted.isChange

      return noted.seen
    })

    if (isChange && (await read($, samples)).length > 0) {
      await $.state.set({ ...changedAt, id: 'tools' }, await $.clock.now())
    }

    return result
  })

  // The band above the prompt, desktop only, kept to one quiet row: ring,
  // clock and Details. Hit rate, context and the trend line show on hover;
  // a break mark and the extend button appear only when they need you.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.surface !== 'desktop' || e.props.hasSurvey) {
      return next(e)
    }

    // Set even when the band is off: the desktop keeps no status line then.
    hasBand = true
    // Redraw on the stage, not every second: the ring and the clock count down
    // by SMIL, and a per-second redraw of the band resets an open Select's
    // highlight in the panel too.
    await read($, stage)
    applyPicks(await read($, overrides))

    if (config.band === 'off') {
      return next(e)
    }

    const { Box, Text, Button, Svg } = $.ui.resolve(e)
    const now = await $.clock.now()
    const list = await read($, samples)
    const last = list.at(-1)
    const s = strings
    const details = (
      <Button
        key="details"
        plain
        dimColor
        label={s.details}
        onPress={() => {
          forgetPaneDrawings()
          void $.ui.open({ id: PANE, title: s.paneTitle })
        }}
      />
    )

    if (last === undefined) {
      return (
        <Box key="band" flexDirection="row" alignItems="center" gap={1}>
          <Svg key="ring" alt={s.ringAlt} source={idleRingSvg()} width={RING_SIZE} height={RING_SIZE} />
          {details}
          <Box display="none" hover={{ display: 'flex' }}>
            <Text dimColor>{s.waiting}</Text>
          </Box>
        </Box>
      )
    }

    const breakList = await read($, breaks)
    const countdown = countdownOf(list, await read($, extensions), config.ttlMode, await read($, ttl), config, now)
    const isExtending = await read($, extending)

    if (countdown === null) {
      return next(e)
    }

    const context = formatTokens(contextOf(last))
    const isAnswering = e.props.isWorking
    const ringKey = isAnswering ? 'working' : `${countdown.anchor}|${countdown.ttl}|${countdown.phase}`

    if (ring.key !== ringKey) {
      ring = { key: ringKey, source: isAnswering ? pausedRingSvg() : ringSvg(countdown) }
    }

    const lastBreak = breakList.at(-1)
    const didBreak = lastBreak !== undefined && lastBreak.at === last.sentAt
    const isExpired = !isAnswering && countdown.phase === 'expired'
    const canExtend = !isAnswering && countdown.phase === 'alert' && config.onExpiring !== 'notify'
    const clockColor =
      countdown.phase === 'warn' ? COLORS.warn : countdown.phase === 'alert' ? COLORS.alert : COLORS.neutral

    if (smallClock.key !== ringKey) {
      smallClock = { key: ringKey, ...clockSvg(countdown.leftMs, clockColor, CLOCK_SIZE) }
    }

    return (
      <Box key="band" flexDirection="row" alignItems="center" gap={1}>
        <Svg key="ring" alt={s.ringAlt} source={ring.source} width={RING_SIZE} height={RING_SIZE} />
        {/* Answering: the countdown waits, since each request refreshes the cache. */}
        {isAnswering ? (
          <Text dimColor>…</Text>
        ) : isExpired ? null : (
          <Svg
            key="clock"
            alt={formatClock(countdown.leftMs)}
            source={smallClock.source}
            width={smallClock.width}
            height={smallClock.height}
          />
        )}
        {isExtending ? (
          <Text dimColor>{s.extending}</Text>
        ) : canExtend ? (
          <Button key="extend" variant="primary" label={s.extendShort} onPress={() => void extendNow?.('manual')} />
        ) : null}
        {details}
        {didBreak ? (
          <Box key="break" flexDirection="row" gap={1}>
            <Text color={TEXT_ALERT}>⚠</Text>
            <Box display="none" hover={{ display: 'flex' }}>
              <Text color={TEXT_ALERT}>{s.broke(formatCauses(lastBreak.causes, s))}</Text>
            </Box>
          </Box>
        ) : null}
        {/* Shown while the pointer is over the band; after the buttons, so it never moves them. */}
        <Box display="none" hover={{ display: 'flex' }} flexDirection="row" alignItems="center" gap={1}>
          {isExpired ? (
            <Text dimColor>
              {s.expired} · {s.rewriteNext(context)}
            </Text>
          ) : null}
          <Text>
            <Text dimColor>{s.hit} </Text>
            {formatPercent(hitRateOf(last))}
          </Text>
          <Text>
            <Text dimColor>{s.context} </Text>
            {context}
          </Text>
          {list.length > 1 ? (
            <Svg
              key="spark"
              alt={s.sparkAlt}
              source={sparklineSvg(recentHits(list, breakList, SPARK_POINTS))}
              width={SPARK_WIDTH}
              height={SPARK_HEIGHT}
            />
          ) : null}
        </Box>
      </Box>
    )
  })

  on('ui.close', async ($, e, next) => {
    if (e.id === PANE) {
      forgetPaneDrawings()
    }

    return next(e)
  })

  // The side panel: the countdown large, this conversation's totals, the
  // per-request chart, breaks, extensions and quick settings. Drawings where
  // the surface has Svg; the terminal gets the text.
  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const ui = $.ui.resolve(e)
    const { Box, Text, Button } = ui
    const Svg = 'Svg' in ui ? ui.Svg : null
    const Select = 'Select' in ui ? ui.Select : null
    // Redraw on the stage, not every second: the ring and clock count down by
    // SMIL. Without Svg (the terminal) the clock is text, so it reads `now`.
    await read($, stage)
    applyPicks(await read($, overrides))
    const s = strings

    if (Svg === null) {
      await read($, clock)
    }

    const now = await $.clock.now()
    const list = await read($, samples)
    const breakList = await read($, breaks)
    const extensionList = await read($, extensions)
    const learned = await read($, ttl)
    const isExtending = await read($, extending)
    const last = list.at(-1)
    const countdown = countdownOf(list, extensionList, config.ttlMode, learned, config, now)

    const setOption = async (field: QuickSetting, value: string) => {
      const failed = await pickOption?.(field, value)

      if (failed !== null && failed !== undefined) {
        $.ui.toast(failed)
      }
    }

    // How the TTL was settled; it explains the TTL setting, so it sits there.
    const ttlNote =
      config.ttlMode !== 'auto'
        ? null
        : learned.detected === '1h' && learned.idleMs !== null
          ? s.ttlLearned('1h', Math.floor(learned.idleMs / 60_000))
          : s.ttlAssumed
    const title = (text: string) => <Text bold>{text}</Text>
    const stat = (label: string, value: string) => (
      <Text>
        <Text dimColor>{label} </Text>
        {value}
      </Text>
    )

    const toastName = (isOn: boolean) => (isOn ? s.toastOptions.on : s.toastOptions.off)
    const sensitivitySelect =
      Select === null ? null : (
        <Box flexDirection="column">
          <Text dimColor>{s.breakSensitivityLabel}</Text>
          <Select
            key="breakSensitivity"
            value={config.breakSensitivity}
            options={SENSITIVITIES.map(v => ({ value: v, label: s.breakSensitivityOptions[v] }))}
            onSelect={value => void setOption('breakSensitivity', value)}
          />
          <Text dimColor>{s.breakSensitivityNote}</Text>
        </Box>
      )

    const settings = (withSensitivity: boolean) => (
      <Box flexDirection="column">
        {title(s.settingsTitle)}
        {Select === null ? (
          <Text dimColor>
            {s.onExpiringLabel}: {s.onExpiringOptions[config.onExpiring]}
            {config.onExpiring === 'auto' ? ` (${s.autoExtendTimes(config.autoExtendMaxPerIdle)})` : ''} ·{' '}
            {s.toastLabel}: {toastName(config.toast)} · {s.ttlModeLabel}: {s.ttlModeOptions[config.ttlMode]} ·{' '}
            {s.bandLabel}: {s.bandOptions[config.band]} · {s.breakSensitivityLabel}:{' '}
            {s.breakSensitivityOptions[config.breakSensitivity]} · {s.languageLabel}: {LANGUAGE_NAMES[config.language]}
            {ttlNote === null ? '' : `\n${ttlNote}`}
          </Text>
        ) : (
          <Box flexDirection="column" gap={1}>
            <Box flexDirection="column">
              <Text dimColor>{s.onExpiringLabel}</Text>
              <Select
                key="onExpiring"
                value={config.onExpiring}
                options={(['notify', 'button', 'auto'] as const).map(v => ({ value: v, label: s.onExpiringOptions[v] }))}
                onSelect={value => void setOption('onExpiring', value)}
              />
            </Box>
            {/* Only automatic extension has a limit to set. */}
            {config.onExpiring === 'auto' ? (
              <Box flexDirection="column">
                <Text dimColor>{s.autoExtendMaxLabel}</Text>
                <Select
                  key="autoExtendMaxPerIdle"
                  value={String(config.autoExtendMaxPerIdle)}
                  options={autoExtendSteps(config.autoExtendMaxPerIdle).map(n => ({
                    value: String(n),
                    label: s.autoExtendTimes(n),
                  }))}
                  onSelect={value => void setOption('autoExtendMaxPerIdle', value)}
                />
              </Box>
            ) : null}
            <Box flexDirection="column">
              <Text dimColor>{s.toastLabel}</Text>
              <Select
                key="toast"
                value={String(config.toast)}
                options={[true, false].map(v => ({ value: String(v), label: toastName(v) }))}
                onSelect={value => void setOption('toast', value)}
              />
            </Box>
            <Box flexDirection="column">
              <Text dimColor>{s.ttlModeLabel}</Text>
              <Select
                key="ttlMode"
                value={config.ttlMode}
                options={(['auto', '5m', '1h'] as const).map(v => ({ value: v, label: s.ttlModeOptions[v] }))}
                onSelect={value => void setOption('ttlMode', value)}
              />
              {ttlNote === null ? null : <Text dimColor>{ttlNote}</Text>}
            </Box>
            <Box flexDirection="column">
              <Text dimColor>{s.bandLabel}</Text>
              <Select
                key="band"
                value={config.band}
                options={(['compact', 'off'] as const).map(v => ({ value: v, label: s.bandOptions[v] }))}
                onSelect={value => void setOption('band', value)}
              />
            </Box>
            {withSensitivity ? sensitivitySelect : null}
            <Box flexDirection="column">
              <Text dimColor>{s.languageLabel}</Text>
              <Select
                key="language"
                value={config.language}
                options={LANGUAGES.map(v => ({ value: v, label: LANGUAGE_NAMES[v] }))}
                onSelect={value => void setOption('language', value)}
              />
            </Box>
          </Box>
        )}
      </Box>
    )

    if (last === undefined || countdown === null) {
      return (
        <Box flexDirection="column" gap={1}>
          <Box flexDirection="row" alignItems="center" gap={2}>
            {Svg === null ? null : (
              <Svg
                key="ring"
                alt={s.ringAlt}
                source={idleRingSvg(BIG_RING_SIZE)}
                width={BIG_RING_SIZE}
                height={BIG_RING_SIZE}
              />
            )}
            <Text dimColor>{s.waiting}</Text>
          </Box>
          {settings(true)}
        </Box>
      )
    }

    const context = formatTokens(contextOf(last))
    const ringKey = isWorking ? 'working' : `${countdown.anchor}|${countdown.ttl}|${countdown.phase}`

    if (bigRing.key !== ringKey) {
      bigRing = { key: ringKey, source: isWorking ? pausedRingSvg(BIG_RING_SIZE) : ringSvg(countdown, BIG_RING_SIZE) }
    }

    const clockColor =
      countdown.phase === 'warn' ? COLORS.warn : countdown.phase === 'alert' ? COLORS.alert : undefined

    if (bigClock.key !== ringKey) {
      bigClock = { key: ringKey, ...clockSvg(countdown.leftMs, clockColor ?? COLORS.neutral, BIG_CLOCK_SIZE) }
    }

    const canExtend = !isWorking && countdown.phase === 'alert' && config.onExpiring !== 'notify'
    const summary = summarize(list, breakList, extensionList)
    const isQuiet = breakList.length === 0 && extensionList.length === 0
    // A narrow panel gets fewer, wider bars and a three-line readout. Its
    // width comes in cells; ~8.7px each on desktop, a guess only for spacing.
    const isNarrow = e.props.bodyColumns < NARROW_COLUMNS
    const chart = chartModel(
      list,
      breakList,
      extensionList,
      config.ttlMode,
      learned,
      isNarrow ? NARROW_CHART_BARS : CHART_BARS,
      config.warnAtPercent,
    )
    const chartFirst = chart.bars[0]?.number ?? 0
    const chartMarks = legendMarks(chart)
    const chartDrawing = chartSvg(
      chart,
      `${chart.isCapped ? '≤ ' : ''}${formatTokens(Math.round(chart.top))}`,
      s.chartRange(chartFirst, chartFirst + chart.bars.length - 1),
      chart.bars.map(bar => readoutOf(bar, s, isNarrow)),
      e.props.bodyColumns * 8.7,
    )
    // The request an extension kept warm: the last one sent before it.
    const idleSince = (at: number) => [...list].reverse().find(x => x.sentAt < at)?.sentAt ?? null
    const numberOf = (sentAt: number) => {
      const i = list.findIndex(x => x.sentAt === sentAt)

      return i < 0 ? null : i + 1
    }
    const swatch = (color: string, glyph: string, label: string) => (
      <Text>
        <Text color={color}>{glyph}</Text>
        <Text dimColor> {label}</Text>
      </Text>
    )

    return (
      <Box flexDirection="column" gap={1}>
        <Box flexDirection="row" alignItems="center" gap={2}>
          {Svg === null ? null : (
            <Svg key="ring" alt={s.ringAlt} source={bigRing.source} width={BIG_RING_SIZE} height={BIG_RING_SIZE} />
          )}
          <Box flexDirection="column">
            {isWorking ? (
              <Text dimColor>{s.working}</Text>
            ) : countdown.phase === 'expired' ? (
              <Text dimColor>
                {s.expired} · {s.rewriteNext(context)}
              </Text>
            ) : Svg === null ? (
              <Text bold color={clockColor}>
                {formatClock(countdown.leftMs)}
              </Text>
            ) : (
              <Svg
                key="clock"
                alt={formatClock(countdown.leftMs)}
                source={bigClock.source}
                width={bigClock.width}
                height={bigClock.height}
              />
            )}
            <Text dimColor>
              TTL {s.ttl(config.ttlMode, countdown.ttl)} · {s.lastHit} {formatPercent(hitRateOf(last))} · {s.context}{' '}
              {context}
            </Text>
          </Box>
          {isExtending ? (
            <Text dimColor>{s.extending}</Text>
          ) : canExtend ? (
            <Button
              key="extend"
              variant="primary"
              label={s.extend(context)}
              onPress={() => void extendNow?.('manual')}
            />
          ) : null}
        </Box>

        <Box flexDirection="column">
          {title(s.summaryTitle)}
          <Text>
            {stat(s.averageHit, summary.averageHitRate === null ? '–' : formatPercent(summary.averageHitRate))} ·{' '}
            {stat(s.requests, String(summary.requests))} · {stat(s.breaks, String(summary.breaks))} ·{' '}
            {stat(s.extensionsCount, String(summary.extensions))} ·{' '}
            {stat(s.peakContext, formatTokens(summary.peakContext))}
          </Text>
        </Box>

        {Svg === null ? null : (
          <Box flexDirection="column">
            {title(s.chartTitle)}
            <Svg key="chart" alt={s.chartAlt} source={chartDrawing.source} height={chartDrawing.height} isInteractive />
            {/* What every chart has on one row; the occasional marks, when shown, on a second. */}
            <Box flexDirection="row" columnGap={2} rowGap={0} flexWrap="wrap">
              {/* Opaque swatches: the bars' see-through greys vanish as text. */}
              {swatch(COLORS.neutral, '■', s.legend.read)}
              {swatch(COLORS.written, '■', s.legend.written)}
              {swatch(COLORS.neutral, '□', s.legend.uncached)}
              <Text>
                <Text color={COLORS.neutral}>▬</Text>
                {chartMarks.dip ? <Text color={COLORS.dip}>▬</Text> : null}
                {chartMarks.low ? <Text color={COLORS.warn}>▬</Text> : null}
                <Text dimColor> {s.legend.rate}</Text>
              </Text>
            </Box>
            {chartMarks.broke || chartMarks.gap || chartMarks.extension ? (
              <Box flexDirection="row" columnGap={2} rowGap={0} flexWrap="wrap">
                {chartMarks.broke ? swatch(COLORS.alert, '▬', s.legend.broke) : null}
                {chartMarks.gap ? swatch(COLORS.neutral, '┊', s.legend.gap) : null}
                {chartMarks.extension ? swatch(COLORS.neutral, '▲', s.legend.extension) : null}
              </Box>
            ) : null}
          </Box>
        )}

        {/* Nothing to list: one line says so, rather than two empty sections. */}
        {isQuiet ? (
          <Text dimColor>{s.quietHistory}</Text>
        ) : (
          <Box flexDirection="column" gap={1}>
            <Box flexDirection="column">
              {title(s.breaksTitle)}
              {breakList.length === 0 ? <Text dimColor>{s.noBreaks}</Text> : null}
              {breakList
                .slice(-LIST_ROWS)
                .reverse()
                .map(b => (
                  <Box flexDirection="column">
                    <Text>
                      <Text color={TEXT_ALERT}>● </Text>
                      {s.breakLine(
                        numberOf(b.at),
                        formatPercent(b.previousHitRate),
                        formatPercent(b.hitRate),
                        formatTokens(b.rewritten),
                      )}
                    </Text>
                    <Text dimColor>  {formatCauses(b.causes, s)}</Text>
                  </Box>
                ))}
              {/* Tuned where a misjudged break shows. */}
              {sensitivitySelect === null ? null : <Box marginTop={1}>{sensitivitySelect}</Box>}
            </Box>

            <Box flexDirection="column">
              {title(s.extensionsTitle)}
              {extensionList.length === 0 ? <Text dimColor>{s.noExtensions}</Text> : null}
              {extensionList
                .slice(-LIST_ROWS)
                .reverse()
                .map(x => (
                  <Text>
                    <Text dimColor>{s.idleAt(formatClock(x.at - (idleSince(x.at) ?? x.at)))} · </Text>
                    {s.trigger[x.trigger]} ·{' '}
                    {x.isAnswered ? (
                      s.extensionRead(formatTokens(x.read))
                    ) : (
                      <Text color={TEXT_ALERT}>{s.extensionFailed(x.reason ?? '')}</Text>
                    )}
                  </Text>
                ))}
            </Box>
          </Box>
        )}

        {settings(isQuiet)}
      </Box>
    )
  })

  // /clear starts a new conversation: its first request is a cold write, not a break.
  on('session.end', async ($, e, next) => {
    if (e.reason === 'clear') {
      await update($, samples, () => [])
      await update($, breaks, () => [])
      await update($, extensions, () => [])
      await $.state.set({ ...changedAt, id: 'compact' }, null)
      await $.state.set({ ...changedAt, id: 'system' }, null)
      await $.state.set({ ...changedAt, id: 'tools' }, null)
    }

    return next(e)
  })
}

files.hooks/core.ts:
// Pure logic over plain data: no `$` here, so tests can call it directly.

import type {
  BandMode,
  BreakCause,
  BreakSensitivity,
  CacheBreak,
  CacheSample,
  ChangeMarks,
  Extension,
  Language,
  OnExpiring,
  Override,
  Overrides,
  SessionSummary,
  Ttl,
  TtlMode,
  TtlState,
} from '../types'
import type { Strings } from './i18n'

export const MAX_SAMPLES = 500
export const MAX_EVENTS = 100

const MINUTE = 60_000

export const TTL_MS: Record<Ttl, number> = { '5m': 5 * MINUTE, '1h': 60 * MINUTE }

/** Slack on idle gaps, so clock jitter near a TTL edge proves nothing. */
const IDLE_MARGIN_MS = 15_000

/** Fewer cached tokens than this say nothing about the TTL. */
const MIN_PROOF_TOKENS = 1024

// ---- Config

export type { BandMode, OnExpiring }

export type Config = {
  language: Language
  ttlMode: TtlMode
  onExpiring: OnExpiring
  band: BandMode
  warnAtPercent: number
  alertAtPercent: number
  toast: boolean
  autoExtendMaxPerIdle: number
  autoExtendMinContextK: number
  autoExtendGiveUpMin: number
  breakSensitivity: BreakSensitivity
}

export const LANGUAGES: readonly Language[] = ['en', 'zh-TW']

const pick = <T extends string>(value: unknown, allowed: readonly T[], fallback: T): T =>
  allowed.find(item => item === value) ?? fallback

const clamp = (value: unknown, fallback: number, min: number, max: number) =>
  typeof value === 'number' && Number.isFinite(value) ? Math.min(max, Math.max(min, value)) : fallback

/** Reads `register`'s options, falling back to the defaults on anything odd. */
export const readConfig = (options: Readonly<Record<string, unknown>>): Config => ({
  language: pick(options.language, LANGUAGES, 'en'),
  ttlMode: pick(options.ttlMode, ['auto', '5m', '1h'], 'auto'),
  onExpiring: pick(options.onExpiring, ['notify', 'button', 'auto'], 'button'),
  band: pick(options.band, ['compact', 'off'], 'compact'),
  warnAtPercent: clamp(options.warnAtPercent, 20, 1, 99),
  alertAtPercent: clamp(options.alertAtPercent, 10, 1, 99),
  toast: typeof options.toast === 'boolean' ? options.toast : true,
  autoExtendMaxPerIdle: clamp(options.autoExtendMaxPerIdle, 3, 0, 100),
  autoExtendMinContextK: clamp(options.autoExtendMinContextK, 20, 0, 10_000),
  autoExtendGiveUpMin: clamp(options.autoExtendGiveUpMin, 0, 0, 24 * 60),
  breakSensitivity: pick(options.breakSensitivity, SENSITIVITIES, 'medium'),
})

// ---- Settings picked in the panel

const ON_EXPIRING: readonly OnExpiring[] = ['notify', 'button', 'auto']
const TTL_MODES: readonly TtlMode[] = ['auto', '5m', '1h']
const BAND_MODES: readonly BandMode[] = ['compact', 'off']
export const SENSITIVITIES: readonly BreakSensitivity[] = ['low', 'medium', 'high']

/** The panel's steps for the auto-extend limit; a value set elsewhere is added. */
export const AUTO_EXTEND_STEPS: readonly number[] = [0, 1, 3, 5, 10]

export type QuickSetting = keyof Overrides

/** Overrides by field, typed so a generic field keeps its value's type. */
type Picks = { [K in QuickSetting]: Override<Config[K]> | null }

const oneOf =
  <T extends string>(allowed: readonly T[]) =>
  (value: unknown): value is T =>
    allowed.some(a => a === value)

/** What each field takes: the same bounds `readConfig` holds it to. */
const IS_VALUE: { [K in QuickSetting]: (value: unknown) => value is Config[K] } = {
  onExpiring: oneOf(ON_EXPIRING),
  ttlMode: oneOf(TTL_MODES),
  band: oneOf(BAND_MODES),
  language: oneOf(LANGUAGES),
  breakSensitivity: oneOf(SENSITIVITIES),
  toast: (value): value is boolean => typeof value === 'boolean',
  autoExtendMaxPerIdle: (value): value is number =>
    typeof value === 'number' && Number.isFinite(value) && value >= 0 && value <= 100,
}

export const QUICK_SETTINGS = Object.keys(IS_VALUE) as QuickSetting[]

export const NO_OVERRIDES: Overrides = {
  onExpiring: null,
  ttlMode: null,
  band: null,
  language: null,
  breakSensitivity: null,
  toast: null,
  autoExtendMaxPerIdle: null,
}

/** A Select's string as the field's value, or null when it isn't one. */
export const fromSelect = <K extends QuickSetting>(field: K, raw: string): Config[K] | null => {
  const value: unknown =
    field === 'toast'
      ? raw === 'true'
        ? true
        : raw === 'false'
          ? false
          : null
      : field === 'autoExtendMaxPerIdle'
        ? raw.trim() === ''
          ? null
          : Number(raw)
        : raw

  return IS_VALUE[field](value) ? value : null
}

/** The auto-extend Select's steps, with a value set elsewhere among them. */
export const autoExtendSteps = (current: number): number[] =>
  AUTO_EXTEND_STEPS.includes(current) ? [...AUTO_EXTEND_STEPS] : [...AUTO_EXTEND_STEPS, current].sort((a, b) => a - b)

const isOverride = (field: QuickSetting, value: unknown) =>
  value === null ||
  (typeof value === 'object' &&
    'value' in value &&
    'over' in value &&
    IS_VALUE[field](value.value) &&
    IS_VALUE[field](value.over))

/**
 * A `$.store` value as Overrides, or null when it is malformed. A field saved
 * before it existed (`band`, `language`, `breakSensitivity`, ...) reads as no
 * override, so an upgrade keeps the rest.
 */
export const normalizeOverrides = (value: unknown): Overrides | null => {
  if (typeof value !== 'object' || value === null || !('onExpiring' in value) || !('ttlMode' in value)) {
    return null
  }

  const saved = value as Record<string, unknown>
  const fields = QUICK_SETTINGS.map(field => [field, saved[field] ?? null] as const)

  if (!fields.every(([field, pick]) => isOverride(field, pick))) {
    return null
  }

  return { ...NO_OVERRIDES, ...Object.fromEntries(fields) } as Overrides
}

const applyOne = <K extends QuickSetting>(config: Config, base: Config, field: K, pick: Picks[K]) => {
  if (pick !== null && pick.over === base[field]) {
    config[field] = pick.value
  }
}

/** The settings in force: each override while the value it replaced still stands. */
export const applyOverrides = (base: Config, o: Overrides): Config => {
  const picks: Picks = o
  const config = { ...base }

  for (const field of QUICK_SETTINGS) {
    applyOne(config, base, field, picks[field])
  }

  return config
}

/**
 * Records a pick; picking the `userConfig` value again clears the override,
 * and a value the field doesn't take leaves the picks as they were.
 */
export const withOverride = <K extends QuickSetting>(o: Overrides, base: Config, field: K, value: unknown): Overrides => {
  if (!IS_VALUE[field](value)) {
    return o
  }

  const pick: Override<Config[K]> | null = value === base[field] ? null : { value, over: base[field] }

  return { ...o, [field]: pick }
}

/** Drops the override for `field`, once a `/config` row holds that setting. */
export const withoutOverride = (o: Overrides, field: QuickSetting): Overrides => ({ ...o, [field]: null })

// ---- /cache arguments

/** What `/cache` was asked: open the panel, switch the language, or neither. */
export type CacheCommand = { kind: 'open' } | { kind: 'language'; language: Language } | { kind: 'unknown' }

const LANGUAGE_ALIASES: Partial<Record<string, Language>> = {
  en: 'en',
  english: 'en',
  zh: 'zh-TW',
  'zh-tw': 'zh-TW',
  tw: 'zh-TW',
  中文: 'zh-TW',
  繁中: 'zh-TW',
}

/** Reads `/cache`'s arguments: nothing opens the panel; `lang` alone switches to the other language. */
export const parseCacheArgs = (args: string, current: Language): CacheCommand => {
  const [verb, value, ...rest] = args.trim().toLowerCase().split(/\s+/).filter(word => word !== '')

  if (verb === undefined) {
    return { kind: 'open' }
  }

  if ((verb !== 'lang' && verb !== 'language') || rest.length > 0) {
    return { kind: 'unknown' }
  }

  if (value === undefined) {
    return { kind: 'language', language: current === 'en' ? 'zh-TW' : 'en' }
  }

  const language = LANGUAGE_ALIASES[value]

  return language === undefined ? { kind: 'unknown' } : { kind: 'language', language }
}

// ---- Samples

export type Usage = {
  model: string
  input_tokens: number
  output_tokens: number
  cache_read_input_tokens: number
  cache_creation_input_tokens: number
}

export const toSample = (
  usage: Usage,
  sentAt: number,
  at: number,
  previous: CacheSample | undefined,
): CacheSample => ({
  sentAt,
  at,
  model: usage.model,
  read: usage.cache_read_input_tokens,
  written: usage.cache_creation_input_tokens,
  uncached: usage.input_tokens,
  output: usage.output_tokens,
  idleMs: previous === undefined ? null : sentAt - previous.sentAt,
})

export const appendCapped = <T>(list: readonly T[], item: T, max: number): T[] =>
  [...list, item].slice(-max)

export const inputOf = (s: CacheSample) => s.read + s.written + s.uncached

/** Everything the next request carries: this one's input plus its output. */
export const contextOf = (s: CacheSample) => inputOf(s) + s.output

export const hitRateOf = (s: CacheSample) => {
  const input = inputOf(s)

  return input === 0 ? 0 : s.read / input
}

// ---- TTL

export const effectiveTtl = (mode: TtlMode, ttl: TtlState): Ttl =>
  mode === 'auto' ? (ttl.detected ?? '5m') : mode

export const EMPTY_TTL: TtlState = { detected: null, at: null, idleMs: null }

export const isTtlState = (value: unknown): value is TtlState =>
  typeof value === 'object' &&
  value !== null &&
  'detected' in value &&
  (value.detected === null || value.detected === '5m' || value.detected === '1h')

/**
 * Learns the TTL from one request. A solid hit after more than 5 minutes idle
 * proves 1h. Once 1h is known, a clean miss inside the hour with nothing else
 * to blame sends it back to 5m. `otherCauses` are the break causes besides idle.
 */
export const learnTtl = (
  ttl: TtlState,
  previous: CacheSample,
  sample: CacheSample,
  otherCauses: readonly BreakCause[],
): TtlState => {
  const idle = sample.idleMs

  if (idle === null || idle <= TTL_MS['5m'] + IDLE_MARGIN_MS || idle >= TTL_MS['1h'] - IDLE_MARGIN_MS) {
    return ttl
  }

  const isHit = sample.read >= MIN_PROOF_TOKENS && hitRateOf(sample) >= 0.5

  if (isHit) {
    return ttl.detected === '1h' ? ttl : { detected: '1h', at: sample.sentAt, idleMs: idle }
  }

  const wasCached = previous.read + previous.written >= MIN_PROOF_TOKENS
  const isCleanMiss = sample.read === 0 && sample.written >= MIN_PROOF_TOKENS

  if (ttl.detected === '1h' && wasCached && isCleanMiss && otherCauses.length === 0) {
    return { detected: '5m', at: sample.sentAt, idleMs: idle }
  }

  return ttl
}

// ---- Countdown

/** When the cache was last refreshed: a request sent, or an answered keep-warm fork. */
export const anchorOf = (samples: readonly CacheSample[], extensions: readonly Extension[]) => {
  const times = [
    samples.at(-1)?.sentAt ?? null,
    ...extensions.filter(x => x.isAnswered && x.read > 0).map(x => x.at),
  ].filter((t): t is number => t !== null)

  return times.length === 0 ? null : Math.max(...times)
}

export const remainingMs = (anchor: number, ttl: Ttl, now: number) => anchor + TTL_MS[ttl] - now

/** fresh, then warn and alert as the TTL runs low, then expired. */
export type Phase = 'fresh' | 'warn' | 'alert' | 'expired'

export type Countdown = {
  anchor: number
  ttl: Ttl
  totalMs: number
  leftMs: number
  /** How much of the TTL is left at `warnAtPercent` and `alertAtPercent`, ms. */
  warnMs: number
  alertMs: number
  phase: Phase
}

export const phaseOf = (leftMs: number, warnMs: number, alertMs: number): Phase =>
  leftMs <= 0 ? 'expired' : leftMs <= alertMs ? 'alert' : leftMs <= warnMs ? 'warn' : 'fresh'

/** Where the countdown stands; null before the first request. */
export const countdownOf = (
  samples: readonly CacheSample[],
  extensions: readonly Extension[],
  mode: TtlMode,
  learned: TtlState,
  config: Pick<Config, 'warnAtPercent' | 'alertAtPercent'>,
  now: number,
): Countdown | null => {
  const anchor = anchorOf(samples, extensions)

  if (anchor === null) {
    return null
  }

  const ttl = effectiveTtl(mode, learned)
  const totalMs = TTL_MS[ttl]
  const leftMs = remainingMs(anchor, ttl, now)
  const warnMs = (totalMs * config.warnAtPercent) / 100
  const alertMs = (totalMs * Math.min(config.alertAtPercent, config.warnAtPercent)) / 100

  return { anchor, ttl, totalMs, leftMs, warnMs, alertMs, phase: phaseOf(leftMs, warnMs, alertMs) }
}

// ---- Keeping the cache warm

/** The one user message a keep-warm fork sends after the cached prefix. */
export const KEEP_WARM_PROMPT = 'Reply with the single word: ok'

type ForkUsage = Pick<Usage, 'cache_read_input_tokens' | 'cache_creation_input_tokens'>

/** What `$.model.fork` resolved to, as far as an Extension needs it. */
export type ForkOutcome =
  | { isAnswered: true; usage: ForkUsage }
  | { isAnswered: false; reason: string; usage?: ForkUsage }

/** `at` is when the fork was sent: the cache refreshes there. */
export const toExtension = (outcome: ForkOutcome, at: number, trigger: Extension['trigger']): Extension => ({
  at,
  trigger,
  isAnswered: outcome.isAnswered,
  reason: outcome.isAnswered ? null : outcome.reason,
  read: outcome.usage?.cache_read_input_tokens ?? 0,
  written: outcome.usage?.cache_creation_input_tokens ?? 0,
})

/** Extensions tried since the last real request: this idle stretch's. */
export const extensionsThisIdle = (samples: readonly CacheSample[], extensions: readonly Extension[]) => {
  const since = samples.at(-1)?.sentAt ?? Number.NEGATIVE_INFINITY

  return extensions.filter(x => x.at > since)
}

export type AutoExtendCheck = {
  samples: readonly CacheSample[]
  extensions: readonly Extension[]
  countdown: Countdown
  config: Pick<Config, 'onExpiring' | 'autoExtendMaxPerIdle' | 'autoExtendMinContextK' | 'autoExtendGiveUpMin'>
  now: number
}

/**
 * Whether to extend on its own now: in `auto` mode, once the alert threshold
 * is reached and before expiry, within the three limits (a give-up time of 0
 * means none), and at most one try per refresh (a failed fork leaves the
 * anchor where it was; no retry storm).
 */
export const shouldAutoExtend = ({ samples, extensions, countdown, config, now }: AutoExtendCheck) => {
  const last = samples.at(-1)

  if (config.onExpiring !== 'auto' || last === undefined || countdown.phase !== 'alert') {
    return false
  }

  const tried = extensionsThisIdle(samples, extensions)

  return (
    tried.length < config.autoExtendMaxPerIdle &&
    contextOf(last) >= config.autoExtendMinContextK * 1000 &&
    (config.autoExtendGiveUpMin === 0 || now - last.sentAt < config.autoExtendGiveUpMin * MINUTE) &&
    tried.every(x => x.at <= countdown.anchor)
  )
}

// ---- Breaks

export const SENSITIVITY: Record<BreakSensitivity, { minContext: number; below: number; above: number }> = {
  low: { minContext: 20_000, below: 0.3, above: 0.85 },
  medium: { minContext: 10_000, below: 0.5, above: 0.8 },
  high: { minContext: 5_000, below: 0.7, above: 0.7 },
}

export const isBreak = (previous: CacheSample, sample: CacheSample, sensitivity: BreakSensitivity) => {
  const t = SENSITIVITY[sensitivity]

  return contextOf(sample) > t.minContext && hitRateOf(sample) < t.below && hitRateOf(previous) > t.above
}

/** What changed between two requests that could have cost the cache, most likely first. */
export const guessCauses = (
  previous: CacheSample,
  sample: CacheSample,
  marks: ChangeMarks,
  ttl: Ttl,
): BreakCause[] => {
  const isBetween = (t: number | null) => t !== null && t > previous.sentAt && t <= sample.at
  const causes: BreakCause[] = []

  if (isBetween(marks.compactAt)) causes.push('compact')
  if (sample.model !== previous.model) causes.push('model')
  if (sample.idleMs !== null && sample.idleMs > TTL_MS[ttl]) causes.push('idle')
  if (isBetween(marks.systemAt)) causes.push('system')
  if (isBetween(marks.toolsAt)) causes.push('tools')

  return causes
}

export const toBreak = (previous: CacheSample, sample: CacheSample, causes: BreakCause[]): CacheBreak => ({
  at: sample.sentAt,
  hitRate: hitRateOf(sample),
  previousHitRate: hitRateOf(previous),
  rewritten: sample.written,
  causes,
})

// ---- Fingerprints of what the prompt is built from

const HASHES_PER_KEY = 8

/** FNV-1a, 32 bits. */
export const hashText = (text: string) => {
  let h = 0x811c9dc5

  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i)
    h = Math.imul(h, 0x01000193)
  }

  return h >>> 0
}

/**
 * Records `text` among the hashes one key has seen. A change is a hash not
 * seen before: remembering several per key keeps a subagent's variant of a
 * section from reading as a change every time it alternates with the main
 * thread's.
 */
export const notePrint = (seen: readonly number[], text: string): { seen: number[]; isChange: boolean } => {
  const hash = hashText(text)

  return seen.includes(hash)
    ? { seen: [...seen], isChange: false }
    : { seen: [...seen, hash].slice(-HASHES_PER_KEY), isChange: true }
}

// ---- Hit-rate history

/** The last `count` samples' hit rates, each with whether it broke the cache. */
export const recentHits = (samples: readonly CacheSample[], breaks: readonly CacheBreak[], count: number) => {
  const broke = new Set(breaks.map(b => b.at))

  return samples.slice(-count).map(s => ({ rate: hitRateOf(s), isBreak: broke.has(s.sentAt) }))
}

// ---- The panel chart

/** What an input token costs against an uncached one: cache writes by TTL. */
export const COST_WEIGHTS = { read: 0.1, written: { '5m': 1.25, '1h': 2 } } as const

/**
 * How long an idle stretch may run before the chart marks it: until the
 * countdown would have turned to warn, `warnAtPercent` of the TTL left. The
 * TTL is the one known when the request was sent; unknown, 5m, as the
 * countdown assumes.
 */
export const gapMarkMs = (ttl: Ttl | null, warnAtPercent: number) =>
  TTL_MS[ttl ?? '5m'] * (1 - warnAtPercent / 100)

/** Fewer bars than this are too few for a percentile: the scale tops at the largest. */
const CAP_MIN_BARS = 10

/** The scale tops at the 90th percentile only when the largest bar is this many times it. */
const CAP_RATIO = 3

/**
 * The TTL a request was written under, as known when it was sent: the mode
 * set, or under auto what had been proved by then; null while nothing had.
 * A later proof leaves earlier requests as they were.
 */
export const ttlWhenSent = (s: CacheSample, mode: TtlMode, learned: TtlState): Ttl | null =>
  mode !== 'auto'
    ? mode
    : learned.detected !== null && learned.at !== null && learned.at <= s.sentAt
      ? learned.detected
      : null

export type Cost = { read: number; written: number; uncached: number }

/** A request's input in uncached-token equivalents; an unknown TTL bills writes as 5m. */
export const costOf = (s: CacheSample, ttl: Ttl | null): Cost => ({
  read: s.read * COST_WEIGHTS.read,
  written: s.written * COST_WEIGHTS.written[ttl ?? '5m'],
  uncached: s.uncached,
})

export const totalOf = (c: Cost) => c.read + c.written + c.uncached

/**
 * Where the chart's scale tops out. Normally at the largest bar; when some
 * dwarf the 90th percentile (a break rewrites the whole prefix), at the
 * largest of the rest, so the everyday bars stay readable and only those
 * clip. Not at the percentile itself: context grows, so the latest bars are
 * the tallest everyday ones, and they would clip every time.
 */
export const chartScale = (totals: readonly number[]): { top: number; isCapped: boolean } => {
  const max = Math.max(0, ...totals)

  if (totals.length < CAP_MIN_BARS) {
    return { top: max, isCapped: false }
  }

  const sorted = [...totals].sort((a, b) => a - b)
  const p90 = sorted[Math.ceil(sorted.length * 0.9) - 1] ?? 0
  const limit = p90 * CAP_RATIO

  return p90 > 0 && max > limit
    ? { top: Math.max(...sorted.filter(t => t <= limit)), isCapped: true }
    : { top: max, isCapped: false }
}

/** The hit-rate strip's colour class: only what needs a look gets a colour. */
export type HitLevel = 'ok' | 'dip' | 'low' | 'broke'

/** The first request has nothing cached to hit, so it reads as ok. */
export const hitLevelOf = (s: CacheSample, isBreak: boolean): HitLevel => {
  if (isBreak) {
    return 'broke'
  }

  if (s.idleMs === null) {
    return 'ok'
  }

  const rate = hitRateOf(s)

  return rate >= 0.95 ? 'ok' : rate >= 0.8 ? 'dip' : 'low'
}

export type ChartBar = {
  /** The request's number in this session, from 1. */
  number: number
  sample: CacheSample
  cost: Cost
  /** Bar height over the scale's top, 0..1. */
  height: number
  isClipped: boolean
  level: HitLevel
  isLatest: boolean
  /** Whether the write weight came from a known TTL. */
  isTtlKnown: boolean
  /** The idle before this request when it reached the warn point (gapMarkMs), ms; null otherwise. */
  gapMs: number | null
  /** Answered keep-warm forks since the request before this one. */
  extensionsBefore: number
  /** The break this request caused, if it did. */
  broke: CacheBreak | null
  /** Its model, when it differs from the request before's; null otherwise. */
  newModel: string | null
}

export type ChartModel = {
  bars: ChartBar[]
  /** The scale's top, in uncached-token equivalents. */
  top: number
  isCapped: boolean
  /** Answered keep-warm forks after the latest request. */
  extensionsAfter: number
}

/** The last `count` requests as the panel chart draws them. */
export const chartModel = (
  samples: readonly CacheSample[],
  breaks: readonly CacheBreak[],
  extensions: readonly Extension[],
  mode: TtlMode,
  learned: TtlState,
  count: number,
  warnAtPercent: number,
): ChartModel => {
  const brokeAt = new Map(breaks.map(b => [b.at, b]))
  const kept = extensions.filter(x => x.isAnswered && x.read > 0)
  const start = Math.max(0, samples.length - count)
  const shown = samples.slice(start)
  const ttls = shown.map(s => ttlWhenSent(s, mode, learned))
  const costs = shown.map((s, i) => costOf(s, ttls[i] ?? null))
  const { top, isCapped } = chartScale(costs.map(totalOf))

  const bars = shown.map((s, i): ChartBar => {
    const cost = costs[i]!
    const total = totalOf(cost)
    const previous = samples[start + i - 1]

    return {
      number: start + i + 1,
      sample: s,
      cost,
      height: top === 0 ? 0 : Math.min(1, total / top),
      isClipped: total > top,
      level: hitLevelOf(s, brokeAt.has(s.sentAt)),
      isLatest: i === shown.length - 1,
      isTtlKnown: ttls[i] !== null,
      gapMs: s.idleMs !== null && s.idleMs >= gapMarkMs(ttls[i] ?? null, warnAtPercent) ? s.idleMs : null,
      extensionsBefore:
        previous === undefined ? 0 : kept.filter(x => x.at > previous.sentAt && x.at <= s.sentAt).length,
      broke: brokeAt.get(s.sentAt) ?? null,
      newModel: previous !== undefined && previous.model !== s.model ? s.model : null,
    }
  })
  const latest = shown.at(-1)

  return {
    bars,
    top,
    isCapped,
    extensionsAfter: latest === undefined ? 0 : kept.filter(x => x.at > latest.sentAt).length,
  }
}

/** Which of the chart's occasional marks it shows, so the legend lists only those. */
export type LegendMarks = { dip: boolean; low: boolean; broke: boolean; gap: boolean; extension: boolean }

export const legendMarks = (model: ChartModel): LegendMarks => ({
  dip: model.bars.some(b => b.level === 'dip'),
  low: model.bars.some(b => b.level === 'low'),
  broke: model.bars.some(b => b.level === 'broke'),
  gap: model.bars.some(b => b.gapMs !== null),
  extension: model.extensionsAfter > 0 || model.bars.some(b => b.extensionsBefore > 0),
})

/** A model id as the readout names it: `claude-opus-5-5` reads `opus-5-5`. */
export const shortModel = (model: string) => model.replace(/^claude-/, '').replace(/-\d{8}$/, '')

/** Below this many body columns the panel is narrow: fewer bars, a three-line readout. */
export const NARROW_COLUMNS = 50

/**
 * The chart's readout lines for one request: when it was sent, after how
 * much idle, any keep-warm forks and a model change; then what it cost, or
 * the break it caused. `≈` marks a cost whose write weight is a guess. Two
 * lines, or three when `isNarrow`, the second one split where it would not fit.
 */
export const readoutOf = (bar: ChartBar, s: Strings, isNarrow = false): string[] => {
  const r = s.readout
  const sample = bar.sample
  const line = (parts: readonly (string | null)[]) => parts.filter(x => x !== null).join(' · ')
  const head = line([
    `#${bar.number}`,
    formatTimeOfDay(sample.sentAt),
    // Past the hour, the chart's own `1h05` rather than a clock reading 65:00.
    sample.idleMs === null ? null : r.idle(sample.idleMs < 3_600_000 ? formatClock(sample.idleMs) : formatGap(sample.idleMs)),
    bar.extensionsBefore === 0 ? null : r.extended(bar.extensionsBefore),
    bar.newModel === null ? null : `→ ${shortModel(bar.newModel)}`,
  ])
  const [first, second] =
    bar.broke !== null
      ? [
          [r.broke, r.rewrote(formatTokens(bar.broke.rewritten))],
          [r.likely(formatCauses(bar.broke.causes, s))],
        ]
      : [
          [
            `${r.cost} ${bar.isTtlKnown ? '' : '≈'}${formatTokens(Math.round(totalOf(bar.cost)))}`,
            `${r.hit} ${(hitRateOf(sample) * 100).toFixed(1)}%`,
          ],
          [
            `${r.written} ${formatTokens(sample.written)}`,
            `${r.uncached} ${formatTokens(sample.uncached)}`,
            `${r.read} ${formatTokens(sample.read)}`,
          ],
        ]

  if (isNarrow) {
    return [head, line(first), line(second)]
  }

  // One line: the hit rate goes last, after the token split it comes from.
  return [head, bar.broke !== null ? line([...first, ...second]) : line([first[0]!, ...second, first[1]!])]
}

// ---- Summary

export const summarize = (
  samples: readonly CacheSample[],
  breaks: readonly CacheBreak[],
  extensions: readonly Extension[],
): SessionSummary => {
  const sum = (f: (s: CacheSample) => number) => samples.reduce((n, s) => n + f(s), 0)
  const read = sum(s => s.read)
  const written = sum(s => s.written)
  const uncached = sum(s => s.uncached)
  const input = read + written + uncached

  return {
    startedAt: samples[0]?.sentAt ?? null,
    endedAt: samples.at(-1)?.at ?? null,
    requests: samples.length,
    averageHitRate: input === 0 ? null : read / input,
    breaks: breaks.length,
    extensions: extensions.length,
    read,
    written,
    uncached,
    peakContext: samples.reduce((n, s) => Math.max(n, contextOf(s)), 0),
  }
}

// ---- Formatting

export const formatTokens = (n: number) => (n >= 1000 ? `${(n / 1000).toFixed(1)}k` : String(n))

export const formatPercent = (rate: number) => `${Math.round(rate * 100)}%`

/** Local wall-clock time, hh:mm:ss. */
export const formatTimeOfDay = (ms: number) => {
  const d = new Date(ms)

  return [d.getHours(), d.getMinutes(), d.getSeconds()].map(x => String(x).padStart(2, '0')).join(':')
}

/** An idle gap as the chart labels it: `12m`, or `1h05` past the hour. */
export const formatGap = (ms: number) => {
  const minutes = Math.floor(ms / 60_000)

  return minutes < 60 ? `${minutes}m` : `${Math.floor(minutes / 60)}h${String(minutes % 60).padStart(2, '0')}`
}

/** m:ss, minutes unbounded (a 1h TTL reads 59:12). */
export const formatClock = (ms: number) => {
  const seconds = Math.max(0, Math.ceil(ms / 1000))

  return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`
}

export const formatCauses = (causes: readonly BreakCause[], s: Strings) =>
  causes.length === 0 ? s.unknownCause : causes.map(c => s.causes[c]).join(', ')

/** The slash command that keeps the cache warm, without its slash. */
export const EXTEND_COMMAND = 'cache-extend'

export type StatusView = {
  samples: readonly CacheSample[]
  breaks: readonly CacheBreak[]
  extensions: readonly Extension[]
  ttl: TtlState
  config: Pick<Config, 'ttlMode' | 'onExpiring' | 'warnAtPercent' | 'alertAtPercent'>
  isWorking: boolean
  isExtending: boolean
  now: number
}

/**
 * The one-line status for the terminal and VS Code: `⚡ 3:42 · 94% · 48.2k`,
 * and `⚠ 0:28 /cache-extend` once the cache is about to expire.
 */
export const formatStatus = (v: StatusView, s: Strings) => {
  const last = v.samples.at(-1)
  const countdown = countdownOf(v.samples, v.extensions, v.config.ttlMode, v.ttl, v.config, v.now)

  if (last === undefined || countdown === null) {
    return `⚡ ${s.waiting}`
  }

  const context = formatTokens(contextOf(last))
  const tail = [formatPercent(hitRateOf(last)), context]
  const lastBreak = v.breaks.at(-1)

  if (lastBreak !== undefined && lastBreak.at === last.sentAt) {
    tail.push(`⚠ ${s.broke(formatCauses(lastBreak.causes, s))}`)
  }

  const clock = formatClock(countdown.leftMs)
  const head = v.isExtending
    ? `⚡ ${s.extending}`
    : v.isWorking
      ? `⚡ ${s.working}`
      : countdown.phase === 'expired'
        ? `⚠ ${s.expired} · ${s.rewriteNext(context)}`
        : countdown.phase === 'alert' && v.config.onExpiring !== 'notify'
          ? `⚠ ${clock} /${EXTEND_COMMAND}`
          : countdown.phase === 'fresh'
            ? `⚡ ${clock}`
            : `⚠ ${clock}`

  return [head, ...tail].join(' · ')
}

